dependencies = [
    {"name": "requests", "version": "2.25.0", "severity": "critical"},
    {"name": "flask", "version": "2.0.1", "severity": "low"},
    {"name": "pyyaml", "version": "5.3.1", "severity": "medium"},
]

SEVERITY_ORDER = {"low": 1, "medium": 2, "high": 3, "critical": 4}
BLOCK_THRESHOLD = SEVERITY_ORDER["critical"]

def scan(deps):
    blocking = [d for d in deps if SEVERITY_ORDER[d["severity"]] >= BLOCK_THRESHOLD]
    return blocking

blocking = scan(dependencies)
for d in dependencies:
    print(f"{d['name']} {d['version']}: severidad {d['severity']}")

if blocking:
    names = ", ".join(d["name"] for d in blocking)
    print(f"BUILD BLOQUEADO: dependencias criticas sin resolver: {names}")
else:
    print("BUILD OK: sin vulnerabilidades criticas")
